------------ import ------------
local ReverseScale = CS.Game.Native.Common.ReverseScale
------------ import ------------

------------ define ------------
local PrefabName = 'RewardNode'
local GoodsNodePath = "Game.Behaviours.GoodNodeMB"
------------ define ------------

---@class TrailRewardBestNode
---@field ListView                      	SuperScrollView.LoopGridView
---@field NameText                      	UnityEngine.UI.Text
---@field RankLvText                    	UnityEngine.UI.Text
local TrailRewardBestNode = Class('TrailRewardBestNode')

function TrailRewardBestNode:__init()
    self.data = nil
end

function TrailRewardBestNode:__delete()
    self.data = nil
end


function TrailRewardBestNode:Awake()
    self.ListView:InitGridView(0, Bind(self, self.OnGetItemByIndex))
end

---FreshUI
---@param segmentRewardVo TrailSegmentRewardVo
function TrailRewardBestNode:FreshUI(segmentRewardVo)
    local spanIds = segmentRewardVo.upGrade
    self.NameText.text = localize('进入总排名的_max_名玩家将获得额外奖励并且<color=#ff3239>不会被降级</color>', {_max_ = spanIds[2]})
    self.RankLvText.text = localize('总榜No. <size=26>_low~_max</size>', {_low = spanIds[1], _max = spanIds[2]})
    self.data = segmentRewardVo.upRewards
    GameUtils.ReloadData(self.ListView, #self.data)
end

---@param listView SuperScrollView.LoopGridView
function TrailRewardBestNode:OnGetItemByIndex(listView, index, row, column)
    if index < 0 then
        return
    end
    local position = index + 1
    if self.data and position <= #self.data  then
        local cell = listView:NewListViewItem(PrefabName)
        local dojo = self.data[position]
        if not isNull(dojo) then
            local goodNodeTrans = cell.transform:Find("GoodNode")
            if not isNull(goodNodeTrans) then
                local reScale = goodNodeTrans.gameObject:GetComponent(typeof(ReverseScale))
                reScale:ResetScale()
                local goodItemNodeMB = GetLuaBehaviour(goodNodeTrans.gameObject, GoodsNodePath)
                if not isNull(goodItemNodeMB) then
                    if isNull(goodItemNodeMB.Env) then
                        goodItemNodeMB:Init()
                    end
                    ---@type GoodNodeMB
                    local goodItemNodeEnv = goodItemNodeMB.Env
                    goodItemNodeEnv:Reload({
                        goodsId = dojo.goodsId, isShowNo = true, text = 'x' .. FormatCurrencyNum(dojo.goodsNum)
                    })
                    goodItemNodeEnv:SetClickButtonAction(function(goodsId)
                        local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
                        if isTable(vo) then
                            GameUtils.ShowCommonTipsBoard(cell.gameObject, vo.name, vo.desc, vo.quality, vo.id)
                        end
                    end)
                end
            end
        end
        return cell
    end
end

function TrailRewardBestNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return TrailRewardBestNode